package test;
import org.eclipse.jdt.core.IJavaProject;
import org.eclipse.jdt.core.IJavaElement;

public class Test {
    public void checkClasspath(IJavaProject javaProject, IJavaElement je) {
        if (javaProject != null && je != null && je.exists() && javaProject.exists()) {
            if (javaProject.equals(je) || javaProject.isOnClasspath(je)) {
                System.out.println("Element is on project classpath.");
            } else {
                System.out.println("Element is NOT on project classpath.");
            }
        }
    }
}

